import os, json, re, csv, io
import xml.etree.ElementTree as ET

base = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_10"

records = []  # list of dicts

def norm(s):
    if s is None: return ""
    return re.sub(r"\s+", " ", str(s)).strip()

def extract_pdf_text(path):
    # try common libs
    for lib in ["pypdf", "PyPDF2", "pdfplumber", "fitz"]:
        try:
            if lib == "fitz":
                import fitz
                doc = fitz.open(path)
                return "\n".join(p.get_text() for p in doc)
            elif lib == "pypdf":
                from pypdf import PdfReader
                return "\n".join(p.extract_text() or "" for p in PdfReader(path).pages)
            elif lib == "PyPDF2":
                import PyPDF2
                return "\n".join(p.extract_text() or "" for p in PyPDF2.PdfReader(path).pages)
            elif lib == "pdfplumber":
                import pdfplumber
                with pdfplumber.open(path) as pdf:
                    return "\n".join((pg.extract_text() or "") for pg in pdf.pages)
        except Exception as e:
            continue
    return None

def parse_md_txt(text):
    d = {}
    m = re.search(r"RECORD:\s*(CB-DOC-\d+-\d+)", text)
    if m: d["record_id"] = m.group(1)
    m = re.search(r"PORTFOLIO KEY:\s*(CBP-\d+-\d+)", text)
    if m: d["portfolio_key"] = m.group(1)
    m = re.search(r"EVIDENCE ROLE:\s*([A-Za-z_]+)", text)
    if m: d["evidence_role"] = m.group(1)
    m = re.search(r"ENTITY KEY:\s*(ENT-\d+-\d+)", text)
    if m: d["immutable_entity_key"] = m.group(1)
    m = re.search(r"REFERENCED REVISION:\s*(REV-\S+)", text)
    if m: d["referenced_revision"] = m.group(1)
    m = re.search(r"CURRENT REVISION:\s*(REV-\S+)", text)
    if m: d["current_revision"] = m.group(1)
    # subject: from markdown title or native record "— X record"
    m = re.search(r"#\s*(.+?)\s*—\s*CB-DOC", text)
    if m: d["subject"] = norm(m.group(1))
    # native record body
    m = re.search(r"NATIVE RECORD\s*\n(.+?)\n\n(?:SOURCE LINEAGE|RELIANCE LIMITS)", text, re.S)
    if m: d["body"] = norm(m.group(1))
    return d

def parse_eml(text):
    d = {}
    m = re.search(r"X-Portfolio-Key:\s*(CBP-\d+-\d+)", text)
    if m: d["portfolio_key"] = m.group(1)
    m = re.search(r"X-Source-System:\s*(.+)", text)
    # subject from header Subject: ... "— X source export"
    m = re.search(r"Subject:\s*(.+)", text)
    if m: d["subject"] = norm(m.group(1))
    # native record: text between first blank line after headers and "SOURCE LINEAGE"
    m = re.search(r"\n\n(.+?)\n\nSOURCE LINEAGE", text, re.S)
    if m: d["body"] = norm(m.group(1))
    m = re.search(r"X-Matter-Number:\s*(CB-LD-\d+)", text)
    return d

def parse_html(text):
    d = {}
    m = re.search(r"<title>(CB-DOC-\d+-\d+)</title>", text)
    if m: d["record_id"] = m.group(1)
    m = re.search(r"<h1>(.*?)</h1>", text)
    if m: d["subject"] = norm(m.group(1))
    m = re.search(r"Portfolio key</dt><dd>(CBP-\d+-\d+)</dd>", text)
    if m: d["portfolio_key"] = m.group(1)
    m = re.search(r"Evidence role</dt><dd>([A-Za-z_]+)</dd>", text)
    if m: d["evidence_role"] = m.group(1)
    m = re.search(r"Entity</dt><dd>(ENT-\d+-\d+)</dd>", text)
    if m: d["immutable_entity_key"] = m.group(1)
    m = re.search(r"Revision</dt><dd>(REV-\S+)</dd>", text)
    if m: d["current_revision"] = m.group(1); d["referenced_revision"] = m.group(1)
    m = re.search(r"<h2>Native record</h2><p>(.*?)</p>", text, re.S)
    if m: d["body"] = norm(m.group(1))
    return d

for dirname in sorted(os.listdir(base)):
    dpath = os.path.join(base, dirname)
