                d["body"] = j.get("body")
                d["custodian"] = j.get("custodian")
                d["reviewer"] = j.get("reviewer")
                d["source_system"] = j.get("source_system")
            elif ext == "csv":
                rows = list(csv.DictReader(io.StringIO(txt)))
                d["record_id"] = rows[0].get("record_id")
