def native_body(text):
    # return text between first "NATIVE RECORD" (case-insensitive, may have ##) and next section header
    m = re.search(r"(?i)native\s*record\s*\n+(.+?)\n+(?:SOURCE LINEAGE|RELIANCE LIMITS|NATIVE ROWS|SCHEDULE)", text, re.S)
    if m: return re.sub(r"\s+"," ", m.group(1)).strip()
    return None

def get_subject(text):
    # md: "# Subject — CB-DOC"; txt: first line title; xml native-record "— Subject record N"
    m = re.search(r"(?i)(?:^|\n)(?:#{1,3}\s*)?([A-Z][A-Za-z\- ]+?)\s*(?:—|-)\s*CB-DOC", text)
    if m: return m.group(1).strip()
    m = re.search(r"—\s*([A-Za-z][A-Za-z\- ]+?)\s*record \d+", text)
