        rows=list(csv.DictReader(io.StringIO(txt)))
        key=rows[0].get("portfolio_key") if rows else None
        for r in rows:
            if r.get("row_type")=="metadata" and r.get("key") in ("evidence_role","body","subject"):
                if r["key"]=="evidence_role": role=r["value"]
                if r["key"]=="body": body=r["value"]
                if r["key"]=="subject": subject=r["value"]
    elif ext=="xml":
        root=ET.fromstring(txt)
        def g(t):
            e=root.find(t); return e.text if e is not None else None
        key=g("portfolio-key"); role=g("evidence-role"); body=g("native-record")
        if body:
            m=re.search(r"—\s*([A-Za-z][A-Za-z\- ]+?)\s*record \d+", body)
