        m=re.search(r"Evidence role</dt><dd>([A-Za-z_]+)</dd>",txt); role=m.group(1) if m else None
        m=re.search(r"<h2>Native record</h2><p>(.*?)</p>",txt,re.S); body=re.sub(r"\s+"," ",m.group(1)).strip() if m else None
        m=re.search(r"<h1>(.*?)</h1>",txt); subject=m.group(1).strip() if m else None
    elif ext in ("md","txt","eml"):
        m=re.search(r"(?:PORTFOLIO KEY|X-Portfolio-Key):\s*(CBP-\d+-\d+)", txt, re.I)
        if m: key=m.group(1)
        m=re.search(r"(?:EVIDENCE ROLE):\s*([A-Za-z_]+)", txt, re.I); 
